{
  "name": "Tango设备属性代理",
  "name_en": "Tango Device Attribute Proxy",
  "manufacturer": "",
  "description": "用于 TANGO 控制系统的通用属性代理，可连接实验室中受 TANGO 管理的仪器或子系统，并对其属性进行读取、写入、轮询和事件订阅。它本身不对应某一种单一物理设备，而是面向各类通过 TANGO 暴露属性的实验硬件。",
  "description_en": "A generic attribute proxy for the TANGO control system, used to connect to laboratory instruments or subsystems managed by TANGO and to read, write, poll, and subscribe to their attributes. It does not correspond to one specific physical device, but rather to a wide range of experimental hardware exposing attributes through TANGO.",
  "tag_hints": [
    "Tango Controls",
    "device attribute access",
    "event subscription",
    "attribute polling",
    "laboratory control system"
  ],
  "actions": [
    {
      "action_name": "auto-get",
      "description": "读取当前属性值",
      "description_en": "Read the current attribute value"
    },
    {
      "action_name": "auto-get_w_value",
      "description": "读取当前属性值及写入值（若可用）",
      "description_en": "Read the current attribute value together with the write value when available"
    },
    {
      "action_name": "auto-put",
      "description": "写入属性值",
      "description_en": "Write an attribute value"
    },
    {
      "action_name": "auto-get_config",
      "description": "获取属性配置",
      "description_en": "Get the attribute configuration"
    },
    {
      "action_name": "auto-get_reading",
      "description": "获取当前读数及相关信息",
      "description_en": "Get the current reading and related metadata"
    },
    {
      "action_name": "auto-has_subscription",
      "description": "检查是否已启用订阅",
      "description_en": "Check whether a subscription is active"
    },
    {
      "action_name": "auto-subscribe_callback",
      "description": "订阅属性更新回调",
      "description_en": "Subscribe a callback for attribute updates"
    },
    {
      "action_name": "auto-unsubscribe_callback",
      "description": "取消属性更新回调订阅",
      "description_en": "Unsubscribe the callback for attribute updates"
    },
    {
      "action_name": "auto-set_polling",
      "description": "设置属性轮询参数",
      "description_en": "Set polling parameters for the attribute"
    },
    {
      "action_name": "auto-set_converter",
      "description": "设置数据转换器",
      "description_en": "Set the data converter"
    },
    {
      "action_name": "auto-poll",
      "description": "轮询属性并在变化时更新",
      "description_en": "Poll the attribute and update on change"
    },
    {
      "action_name": "auto-datatype_allowed",
      "description": "检查是否允许该数据类型",
      "description_en": "Check whether the datatype is allowed"
    },
    {
      "action_name": "auto-set_trl",
      "description": "设置 TANGO 资源定位符",
      "description_en": "Set the TANGO resource locator"
    },
    {
      "action_name": "auto-source",
      "description": "获取数据源设置",
      "description_en": "Get the data source setting"
    },
    {
      "action_name": "auto-get_datakey",
      "description": "获取数据键标识",
      "description_en": "Get the data key identifier"
    },
    {
      "action_name": "auto-get_value",
      "description": "读取当前属性值",
      "description_en": "Get the current attribute value"
    },
    {
      "action_name": "auto-get_setpoint",
      "description": "获取设定值",
      "description_en": "Get the setpoint value"
    },
    {
      "action_name": "auto-set_callback",
      "description": "设置更新回调函数",
      "description_en": "Set the update callback function"
    },
    {
      "action_name": "auto-allow_events",
      "description": "获取是否允许事件更新",
      "description_en": "Get whether event-based updates are allowed"
    }
  ]
}

